from author import *
c=C('二重积分与积分区域')
S(c,'二重积分：先认区域与被积函数',[R('基本形式',r'I=\iint_D f(x,y)\,dA'),R('被积函数为一',r'\iint_D1\,dA=\operatorname{Area}(D)'),T('计算前的三件事','画区域，选积分顺序，写每层上下限')],[P('先把平面区域分成许多小块。二重积分的计算对象包含被积函数和积分区域，两者缺一不可。若被积函数是一，结果就是区域面积；若是非负高度，可以计算相应体积。遇到会取负值的函数，积分可能为负或抵消，不能再把它不加区分地当成几何体积。',[1,2],['区域与被积函数一起决定结果','常数一的二重积分等于面积'],phase='tiles',anchor='先把平面区域分成许多小块'),P('现在沿选定方向扫过这块区域。考试里最重要的是把区域改写成上下限，再用一元积分分层计算。先画草图，标出交点和边界；固定外层变量以后，看内层变量从哪里走到哪里。写出的范围必须与草图一致，不要只凭图形名字抄一个看起来熟悉的积分式。',[3],['固定外层变量，读出内层范围','草图用于检查，不要求画得漂亮'],phase='sweep',anchor='现在沿选定方向扫过这块区域')],['二重积分识别'],visual=G('rectangle'))
S(c,'矩形区域：从内层往外算',[R('题目',r'I=\int_0^1\!dx\int_0^2(x+y)\,dy'),R('内层把x当常数',r'\int_0^2(x+y)dy=2x+2'),R('再算外层',r'I=\int_0^1(2x+2)dx=3'),T('顺序提醒','最里面的微分决定先对谁积分；系数不能提前丢掉')],[P('矩形区域的上下限都是常数，可以先练熟内外层顺序。最里面是对y积分，x当常数，所以x积分得到xy，y积分得到y平方的一半。把y的零与二代进去，得到二x加二。此时y应该已经消失，外层式子里还留着未处理的y，通常说明代限这一步没有完成。',[1,2],['内层对y积分时，x暂时固定','内层代限后不应残留y']),P('外层再对x从零到一积分，得到一加二，结果三。二重积分不是把原式分别随意积分两次，而是一次完成一层，包括原函数、代限和化简。分层写在两行，可以避免把内层常数二漏带到外层，也容易发现变量与上下限是否在中途错配。',[3,4],['先完成内层，再开始外层','本题结果三'])],['直角坐标二重积分'])
S(c,'三角形区域：上下限随外层变化',[R('区域',r'0\leq x\leq1,\quad0\leq y\leq1-x'),R('写成累次积分',r'I=\int_0^1\!dx\int_0^{1-x}(x+y)\,dy'),R('完成计算',r'I=\int_0^1\frac{1-x^2}{2}dx=\frac13')],[P('先固定一条竖直的小线段。三角形由两条坐标轴和x加y等于一围成。外层x从零到一，固定x以后，y从零走到上边界一减x，所以内层上限必须随x变化。如果误写成零到一，就把三角形变成整个单位正方形，第一步的区域已经变了。',[1,2],['竖直切片：下边界到上边界','外层范围取区域在x轴上的投影'],phase='bounds',anchor='先固定一条竖直的小线段'),P('现在让竖直切片扫过整个三角形。内层积分先得到x乘一减x，再加一减x整体平方的一半，化简成一减x平方的一半。外层从零到一积分，结果三分之一。上限含x时，先把内层积分中的x当常数，不需要对上限求导，这里做的是代入上限后的普通积分计算。',[3],['内层先固定x，再把一减x代进去','本题结果三分之一'],phase='sweep',anchor='现在让竖直切片扫过整个三角形')],['一般区域二重积分'],visual=G('triangle'))
S(c,'交换积分次序：先还原同一块区域',[R('原积分',r'I=\int_0^1\!dy\int_y^1 e^{x^2}dx'),R('交换以后',r'I=\int_0^1\!dx\int_0^x e^{x^2}dy'),R('变成容易的一元积分',r'I=\int_0^1xe^{x^2}dx=\frac{e-1}{2}')],[P('先按原式把区域画出来：外层y从零到一，固定y后，x从y到一。因此区域是一条对角线下方的直角三角形。原式内层对x积分，e的x平方没有初等原函数，直接计算不方便；交换顺序可以让内层先对y积分，把这个障碍绕开。',[1,2],['换序先还原区域，不交换两个积分号就结束','同一块区域要重新读上下限'],phase='horizontal',anchor='先按原式把区域画出来'),P('现在改用竖直线段扫过相同区域。x从零到一，每个x对应y从零到x。内层的e的x平方与y无关，积分后乘上区间长度x，得到x乘e的x平方。再令u等于x平方，就算出e减一的一半。换序成功的关键是区域没变，只换了切片方向与积分先后。',[3],['与内层变量无关的量，乘内层区间长度','结果为e减一的一半'],phase='vertical',anchor='现在改用竖直线段扫过相同区域')],['二重积分换序'],visual=G('swap'))
S(c,'极坐标：代变量还要乘r',[R('坐标与面积元',r'x=r\cos\theta,\quad y=r\sin\theta,\quad dA=r\,dr\,d\theta'),R('单位圆盘的范围',r'0\leq r\leq1,\quad0\leq\theta\leq2\pi'),R('例题',r'\iint_D(x^2+y^2)dA=\int_0^{2\pi}\!d\theta\int_0^1r^3dr=\frac\pi2')],[P('先用半径和角度扫出圆盘。出现圆、扇形或x平方加y平方时，考虑极坐标。两个平方和变成r平方，但面积元还要额外乘一个r，所以本题最终是r三次方。只替换被积函数，忘记面积元里的r，是极坐标题最常见的失分点，建议每次先单独写出面积元。',[1,2],['平方和变r平方，面积元再乘r','角度范围与实际扇形一致'],phase='sector',anchor='先用半径和角度扫出圆盘'),P('现在让半径从零扩展到一。整圆的角度是零到二π，半径不是零到二π；两种范围不要对调。内层r三次方积分得到四分之一，再乘角度长度二π，结果π的一半。若区域是圆环，内层下限应改成内半径，不能从零起算而把中央缺失部分一起加进去。',[3],['半径范围与角度范围分别填写','圆环需要非零的半径下限'],phase='radius',anchor='现在让半径从零扩展到一')],['极坐标二重积分'],visual=G('polar'))
S(c,'对称性：区域和函数一起检查',[R('关于y轴对称的单位圆盘',r'\iint_D x\,dA=0'),R('平方项不是奇函数',r'\iint_Dx^2dA=\iint_Dy^2dA'),R('由相等关系求结果',r'2\iint_Dx^2dA=\iint_D(x^2+y^2)dA=\frac\pi2'),R('答案',r'\iint_Dx^2dA=\frac\pi4')],[P('对称性可以减少计算，但必须同时检查区域和被积函数。单位圆盘关于y轴对称，x换成负x时被积函数x反号，所以积分为零。如果区域只剩第一象限，就不能继续用这个结论。区域形状看起来很规则，不代表里面每一个积分都为零，还要看具体的奇偶关系。',[1,2],['奇函数配相应对称区域才抵消','平方项不会因左右对称而抵消']),P('对x平方这一项，反号以后不变，所以不能判零。圆盘交换x和y不改变区域，因此两个平方项的积分相等；把它们相加，正好是上一页已经算过的平方和积分，结果π的一半。每一份占一半，所以得到π除以四。对称性既可以判零，也可以建立相等关系，作用不只有一种。',[3,4],['交换x、y不改变圆盘','相等的两份之和已知，可各取一半'])],['二重积分对称性'])
S(c,'二重积分练习',[R('第一象限四分之一圆盘',r'D:\quad x,y\geq0,\quad x^2+y^2\leq4'),R('任务',r'S(D)=\ ?\qquad \iint_D(x^2+y^2)dA=\ ?')],[P('暂停练习：第一象限内、半径二的四分之一圆盘，先求面积，再求平方和的二重积分。请分别写极坐标范围和两个被积式。角度应对应四分之一圆，面积题的被积函数是一；第二题原来已有一个r平方，再乘面积元的r，不能让两题最后使用完全相同的积分。',[1,2],['半径到二，角度到π的一半','两个被积式分别写清'])],['极坐标二重积分'],kind='question')
S(c,'二重积分练习答案',[R('范围',r'0\leq r\leq2,\quad0\leq\theta\leq\frac\pi2'),R('面积',r'S=\int_0^{\pi/2}\!d\theta\int_0^2r\,dr=\pi'),R('平方和积分',r'I=\int_0^{\pi/2}\!d\theta\int_0^2r^3dr=2\pi')],[P('面积是π，平方和积分是二π。两题角度相同，但内层分别积分r和r三次方，得到二与四，再各乘π的一半。面积也可用半径二的整圆面积除以四作核对。若第二题也算成面积，检查是不是只改了区域，忘记把原被积函数平方和一起转换到极坐标。',[1,2,3],['面积π，平方和积分二π','区域相同不等于积分数值相同'])],['极坐标二重积分'],kind='answer')

c=C('三重积分与积分应用')
S(c,'三重积分：由里向外完成三层',[R('长方体范围',r'0\leq x\leq1,\quad0\leq y\leq2,\quad0\leq z\leq3'),R('体积',r'V=\int_0^1\!dx\int_0^2\!dy\int_0^3 1\,dz=6'),R('换一个被积函数',r'\iiint_\Omega z\,dV=9')],[P('先把长方体的三个方向标出来。三重积分比二重积分多一层，最内层先算，外层变量暂时当常数。被积函数是一时得到体积，本题三条边长一、二、三，积分结果六，正好可以用长宽高核对。三重积分符号本身不表示结果一定是体积，还要看被积函数是什么。',[1,2],['最内层先算，外层变量暂时固定','被积函数一的积分等于体积'],phase='box',anchor='先把长方体的三个方向标出来'),P('现在沿高度方向累加带权的小体积。若被积函数换成z，内层积分z，得到九的一半，再乘y方向长度二和x方向长度一，结果九。这个量与体积六不同。遇到密度或力矩时会出现类似的权重，先识别题目要累加的量，再决定被积函数，不要一见三重积分就直接报体积。',[3],['被积函数改变，计算对象也改变','内层代限后再处理下一层'],phase='weighted',anchor='现在沿高度方向累加带权的小体积')],['直角坐标三重积分'],visual=G('box3'))
S(c,'四面体区域：一层一层读上下限',[R('第一卦限内的区域',r'x,y,z\geq0,\quad x+y+z\leq1'),R('选择先对z积分',r'0\leq x\leq1,\quad0\leq y\leq1-x,\quad0\leq z\leq1-x-y'),R('体积',r'V=\int_0^1\!dx\int_0^{1-x}\!dy\int_0^{1-x-y}1\,dz=\frac16')],[P('先把平面下方的四面体画出来。它在三个坐标方向的截距都是一。若先沿z方向积分，固定x和y以后，底部是z等于零，顶部是z等于一减x减y。再投影到xy平面，得到上一章的三角形，因此y从零到一减x，x从零到一。上下限按这个顺序逐层确定。',[1,2],['先确定最内层上下表面','再投影，读外面两层的范围'],phase='tetra',anchor='先把平面下方的四面体画出来'),P('现在固定一个切片并让它走过投影区域。内层得到一减x减y，第二层积分后是一减x整体平方的一半，最后积分得到六分之一。检查范围时，内层上限可以含外层变量，但外层上限不能依赖尚未定义的内层变量。按三层逐步消去z、y、x，是很实用的自查方法。',[3],['从内到外逐个消去变量','本题体积六分之一'],phase='slice',anchor='现在固定一个切片并让它走过投影区域')],['一般区域三重积分'],visual=G('tetra3'))
S(c,'柱坐标：圆盘底面配高度',[R('变换与体积元',r'x=r\cos\theta,\quad y=r\sin\theta,\quad dV=r\,dr\,d\theta\,dz'),R('半径一、高二的圆柱',r'0\leq r\leq1,\quad0\leq\theta\leq2\pi,\quad0\leq z\leq2'),R('例题',r'\iiint_\Omega(x^2+y^2)dV=\int_0^{2\pi}\!d\theta\int_0^1\!dr\int_0^2r^3dz=\pi')],[P('先扫出圆柱的圆盘底面，再加上高度。柱坐标是把xy平面换成极坐标，z仍然保留。体积元额外乘r，所以被积函数平方和变r平方以后，仍要再乘一个r。本题高度上下限是零和二，与底面位置无关；如果顶部是曲面，z的上限可能还会随r变化。',[1,2],['柱坐标只改变平面两坐标','体积元里的r不能漏'],phase='base',anchor='先扫出圆柱的圆盘底面'),P('现在让高度从零走到二。内层对z积分，r三次方暂时是常数，因此乘高度二；再对r积分得到二分之一，乘整圆角度二π，结果π。图形是圆柱，并不意味着被积函数必为一，本题算的是带平方和权重的积分，不能直接拿圆柱体积二π代替答案。',[3],['先积分z得到高度因子二','本题结果π，不是圆柱体积'],phase='height',anchor='现在让高度从零走到二')],['柱坐标三重积分'],visual=G('cylinder3'))
S(c,'球坐标：半径平方与正弦因子',[R('坐标约定',r'x=\rho\sin\varphi\cos\theta,\quad y=\rho\sin\varphi\sin\theta,\quad z=\rho\cos\varphi'),R('体积元',r'dV=\rho^2\sin\varphi\,d\rho\,d\varphi\,d\theta'),R('半径二的球',r'0\leq\rho\leq2,\quad0\leq\varphi\leq\pi,\quad0\leq\theta\leq2\pi')],[P('先从正z轴向下扫过极角。这里约定φ是与正z轴的夹角，θ仍是平面里的方位角；不同教材字母可能互换，做题必须按坐标公式识别，不能只背一个字母。球坐标体积元是半径平方乘极角正弦，两个因子都要保留，它与柱坐标只乘r并不相同。',[1,2],['极角从正z轴量起','体积元是半径平方乘极角正弦'],phase='angle',anchor='先从正z轴向下扫过极角'),P('现在把半径扩展到二。完整球的极角从零到π，方位角从零到二π，半径从零到二。对常数一积分，半径部分八除以三，极角正弦积分为二，方位角长度二π，体积得到三十二π除以三。若只取上半球，极角范围改成零到π的一半，别只把最后结果随意除二而不写范围。',[3],['完整球与半球的极角范围不同','先写范围，再计算各层积分'],phase='radius',anchor='现在把半径扩展到二')],['球坐标三重积分'],visual=G('sphere3'))
S(c,'质量与重心：先算总量再做比值',[R('密度记作δ，避免与球半径混淆',r'm=\iiint_\Omega\delta\,dV,\quad \bar x=\frac{\iiint_\Omega x\delta\,dV}{m}'),R('均匀四面体例题',r'x,y,z\geq0,\quad x+y+z\leq1,\quad\delta=1'),R('体积、力矩与重心',r'm=\frac16,\quad\iiint_\Omega x\,dV=\frac1{24},\quad(\bar x,\bar y,\bar z)=\left(\frac14,\frac14,\frac14\right)')],[P('质量题在被积函数里放密度，重心坐标则是相应力矩除以总质量。本页用δ表示密度，避免和刚才球坐标的半径字母混淆。若密度为常数，很多比值中的常数可以约去；但密度随位置变化时，就必须把它留在每个积分里，不能直接用几何中心代替质量中心。',[1,2],['质量积分放密度，重心还要除总质量','非恒定密度不能随意约掉']),P('例题是均匀的单位四面体，质量六分之一。按刚才三层范围积分x，得到二十四分之一，除以质量得到x坐标四分之一。由三个坐标的对称性，其余坐标相同。注意它的坐标不是二分之一：四面体的截面随着位置变小，不能把包住它的立方体中心照搬过来。',[3],['本题重心三个坐标均为四分之一','先积分再除质量，不猜外接盒子的中心'])],['重积分应用与重心'])
S(c,'坐标选择与对称性检查',[R('三种体积元',r'dV=dx\,dy\,dz=r\,dr\,d\theta\,dz=\rho^2\sin\varphi\,d\rho\,d\varphi\,d\theta'),R('关于原点对称的球内',r'\iiint_\Omega x\,dV=0'),R('半径一到二的球壳',r'V=\frac{4\pi}{3}(2^3-1^3)=\frac{28\pi}{3}')],[P('选择坐标的目标是让区域和被积函数都简单。平面切出的区域常用直角坐标，圆柱形常用柱坐标，球形常用球坐标。换元因子按维度分别记：平面极坐标乘r，柱坐标体积也乘r，球坐标乘半径平方与极角正弦。不能因为都出现圆，就给所有积分都乘同一个因子。',[1],['坐标选择同时看区域与被积函数','不同面积元和体积元分别记']),P('对称球内积分x，左右配对反号，所以为零。球壳则要保留内半径，体积是外球减内球，得到二十八π除以三。写三重积分时，最后检查区域是否少了孔洞、正负范围或半球限制；这些限制会改变上下限，也会决定对称性是否真的可用。',[2,3],['奇函数配对称区域可抵消','球壳不能从半径零开始算'])],['坐标选择与三重积分对称性'])
S(c,'三重积分练习',[R('第一卦限四面体',r'x,y,z\geq0,\quad x+y+z\leq2'),R('任务',r'V=\ ?')],[P('暂停求体积：三个坐标非负，并且坐标和不超过二。请先写出先z、再y、最后x的三层范围，再计算体积。不要只把上一道单位四面体结果乘二；三个方向都同时扩大，会带来体积按三次方变化。可以用这个尺度关系对最后计算结果作独立核对。',[1,2],['先写三层上下限','三个方向扩大二倍，体积扩大八倍'])],['一般区域三重积分'],kind='question')
S(c,'三重积分练习答案',[R('积分范围',r'V=\int_0^2\!dx\int_0^{2-x}\!dy\int_0^{2-x-y}1\,dz'),R('计算与核对',r'V=\frac43=8\cdot\frac16')],[P('体积是三分之四。先z从零到二减x减y，再y从零到二减x，最后x从零到二。完成三层积分得到三分之四，也正好是单位四面体体积六分之一的八倍。用两种思路核对，有助于发现上下限或少乘因子的错误，但正式解答仍应按题目要求写出积分或必要的几何步骤。',[1,2],['结果三分之四','用尺度三次方检查结果'])],['一般区域三重积分'],kind='answer')
